    let pages = analysis.saved_pages.as_ref().unwrap();
    let same = pages
        .iter()
        .find(|v| v.observation.requested_url == format!("{}/same-doc", site.origin))
        .unwrap();
    assert_eq!(same.original_membership_occurrences, 2);
